/* Skills Library, area A: Business Analysis and Requirements Engineering.
   Every scenario and enterprise example is illustrative unless the evidence note says otherwise.
   Field guide: ev = evidence status of the skill itself ('source' | 'recommended'),
   evNote = where the résumé supports it, artifact = Artifact Studio id, cases = case-study ids. */
window.PF = window.PF || { skills: [], cases: [], artifacts: [], scenarios: [] };

PF.skills.push(
{
  id: 'discovery', area: 'A', name: 'Business problem analysis and discovery',
  tags: ['root cause', 'five whys', 'fishbone', 'problem statement', 'impact analysis', 'current state'],
  ev: 'source', evNote: 'Résumé lists Root Cause Analysis, Business Process Analysis and Business Process Improvement; responsibilities include requirement discovery (Ascra).',
  sum: 'Find out what is actually wrong, for whom, and why, before anyone designs a feature.',
  def: 'Discovery is the structured work of understanding a business problem before committing to a solution. It separates the <em>symptom</em> people report ("too many applications come back"), the <em>root cause</em> that produces it, the <em>business need</em> that must be met, the <em>constraints</em> any answer must respect (policy, budget, existing systems), and the <em>proposed solutions</em> stakeholders bring with them.',
  why: 'Most expensive rework starts with a solution agreed too early. A team that builds "make field X optional" when the real cause is unclear guidance ships a feature, sees no change, and loses a sprint. Discovery keeps the backlog pointed at outcomes and gives every later requirement a reason that can be traced.',
  use: ['A stakeholder arrives with a solution ("add a reminder email") rather than a problem.', 'A metric is moving the wrong way and nobody agrees why.', 'A new module or policy change affects several roles or systems.', 'Complaints are frequent but evidence is anecdotal.'],
  avoid: ['The change is mandated and fully specified by regulation; spend effort on impact analysis instead.', 'A defect with a clear reproduction; triage it, do not run a workshop.', 'The cost of investigating exceeds the cost of a reversible experiment.'],
  steps: ['Write a draft problem statement: who is affected, what happens, how often, what it costs, and what "better" means.', 'Map stakeholders and confirm who owns the process, who owns the policy, and who feels the pain.', 'Document the current-state process from evidence (system records, SOPs, observation), not only from interviews.', 'Collect symptoms and group them. Use Five Whys on the strongest symptom and a fishbone (people, process, policy, system, data, guidance) to keep alternatives open.', 'Turn each candidate cause into a hypothesis that data or observation can confirm or reject.', 'Check the hypotheses with records, sample cases and the people doing the work.', 'Agree the confirmed cause, the business need and the success measure with the process owner, then write requirements.'],
  scenario: 'An authority that processes permission applications sees many files go through repeated clarification cycles. Before proposing anything, the Business Analyst lists four competing explanations. (1) Applicants submit incomplete information. (2) Validation rules are unclear or applied differently by reviewers. (3) The applicant guidance is missing or ambiguous. (4) An internal workflow step sends files back for reasons unrelated to the applicant. The Business Analyst samples closed applications, reads the clarification remarks, and tags each one by cause. If most remarks cite the same missing document, the fix sits in guidance and form validation. If remarks vary by reviewer for the same document, the fix is a published rule and reviewer training. If files return after an internal transfer, the fix is in workflow design.',
  enterprise: 'In a government permission portal, the Business Analyst would prepare a discovery pack for the product owner: a one-paragraph problem statement, a stakeholder map (applicants, reviewing officers, approving authorities, the programme team, the development vendor), a current-state swimlane of submission to clarification, a table of sampled clarification reasons, and ten discovery questions for the next workshop. Example questions: "Which documents are mandatory for every application type, and where is that written down?" and "When a reviewer raises a clarification, can they select a reason, or is it free text?"',
  inputs: ['Stakeholder requests and complaints', 'Existing SOPs, policy circulars and guidelines', 'System records: status history, remarks, timestamps', 'Observation of the people doing the work'],
  outputs: ['Problem statement', 'Stakeholder map', 'Current-state process model', 'Root-cause hypotheses with the evidence for and against', 'Discovery question list', 'Agreed success measure'],
  mistakes: [['Treating the first stakeholder\'s proposed solution as the requirement.', 'Restate it as a problem and ask "what happens today, and how would we know this fixed it?"'], ['Stopping Five Whys at a person ("the reviewer forgot").', 'Keep asking why the process allowed it; people errors usually point to missing guidance or controls.'], ['Interviewing only managers.', 'Include the people who do the work and, where possible, end users.'], ['Treating hypotheses as findings.', 'Label each one as confirmed, rejected or open, and record the evidence.']],
  collab: { biz: 'Agree the problem statement and success measure with the process owner; confirm policy constraints with the policy owner.', design: 'Share pain points and journey evidence so design work starts from user behaviour, not from a feature list.', dev: 'Ask engineers what the system records today and what it would cost to measure the problem.', qa: 'Involve testers early so the success measure and edge cases become test conditions.', pm: 'Give the product owner options with trade-offs rather than a single answer.' },
  tools: ['Miro or FigJam for fishbone and affinity mapping', 'Excel for sampled-case tagging', 'SQL for status and remark analysis', 'Confluence for the discovery page', 'Visio or Draw.io for current-state maps'],
  artifact: 'impact', artifactNote: 'See the Change-impact analysis artifact, which begins with a problem statement and current-state summary.',
  related: ['elicitation', 'gap', 'process', 'discovery-product', 'sqlanalysis'],
  cases: ['rajmarg', 'healthcare'],
  q: { q: 'Tell me about a time you found that the requested solution was not what the business needed.', a: 'I would answer with the clarification example and frame it as my method. The request was to reduce clarification cycles, and the first proposal was to make some fields optional. Before agreeing, I listed the possible causes: incomplete applicant data, inconsistent validation, missing guidance and internal routing. I would explain how I would test each one, for example by sampling clarification remarks and tagging them by cause. The point I would make is that the requirement I eventually wrote addressed the confirmed cause, and that the success measure was agreed before build. If asked for numbers, I would say I do not have measured results I can share.' },
  more: ['How do you know when discovery is finished?', 'How do you handle a senior stakeholder who insists on their solution?', 'What evidence do you trust more than interviews?'],
  honest: 'I describe the discovery method and the evidence I used. Policy decisions and approvals belonged to the client authority, so I say "I prepared the analysis the product owner and client used to decide", not "I decided".'
},
{
  id: 'elicitation', area: 'A', name: 'Stakeholder identification and elicitation',
  tags: ['interviews', 'workshops', 'JAD', 'observation', 'stakeholder register', 'conflicting requirements', 'decision log'],
  ev: 'source', evNote: 'Résumé: Requirement Gathering & Elicitation, Stakeholder Management; JAD sessions (Coditro); collaboration with MoRTH, NHAI, DIC, Engineering, QA and UI/UX teams (Ascra).',
  sum: 'Find the right people, ask the right questions in the right format, and turn disagreement into recorded decisions.',
  def: 'Elicitation draws out requirements, constraints and knowledge from people and documents. Stakeholder identification comes first. It establishes who decides, who owns each process, who uses the system, who builds and supports it, and which external parties the solution depends on.',
  why: 'Requirements written from one viewpoint fail in UAT, when the missing viewpoint finally arrives. Early, deliberate elicitation surfaces conflicting needs while they are still cheap to resolve, and a decision log stops settled questions from being reopened in every meeting.',
  use: ['Any new module, workflow or integration.', 'When a requirement affects several roles with different incentives.', 'When documentation is missing or out of date.'],
  avoid: ['Running large workshops for a narrow, single-owner change; a short interview is enough.', 'Using questionnaires to resolve conflicts; they collect opinions but cannot negotiate.'],
  steps: ['Build a stakeholder register: name or role, organisation, interest, influence, decision rights, preferred channel.', 'Choose a technique for each goal: interviews for depth, workshops for alignment, observation for how work is really done, document analysis for rules, questionnaires for breadth.', 'Prepare: agenda, objective, pre-read, questions, and the decisions needed by the end.', 'Facilitate: restate what you heard, separate needs from solutions, park out-of-scope topics visibly.', 'Within 24 hours, publish notes with decisions, actions (owner and date) and open questions.', 'Track open questions in a register; escalate any that block the backlog.', 'Play the requirements back to stakeholders and confirm sign-off.'],
  scenario: 'An applicant group wants fewer mandatory fields because the form is long. The approving authority needs enough evidence to show the permission was granted in compliance with policy. The Business Analyst does not split the difference by deleting fields. They list each field and record who uses it, at which stage, and under which rule. Fields nobody uses at any stage become candidates for removal. Fields needed only later (for example at the payment or final approval stage) can move to that stage. Fields needed at submission stay, but get clearer help text and examples. The outcome goes into the decision log with the rationale and the approver\'s name.',
  enterprise: 'For a multi-authority portal, the register would distinguish the ministry (policy owner), the implementing authority (process owner and approver), regional offices (reviewers and inspectors), the programme agency (product governance), the engineering vendor, and external services such as payment and e-signature providers. Each open question gets an owner from that register, for example: "OQ-14: Can a provisional approval be issued before the inspection report is uploaded? Owner: approving authority representative. Needed by: sprint 6 refinement."',
  inputs: ['Organisation charts and governance structure', 'Existing SOPs, guidelines and circulars', 'Previous system documentation', 'Complaints, support tickets and change requests'],
  outputs: ['Stakeholder register', 'Elicitation notes', 'Decision log', 'Open-question register', 'Confirmed requirement list'],
  mistakes: [['Treating the loudest stakeholder as the decision-maker.', 'Record decision rights in the register and confirm them with the sponsor.'], ['Leaving workshops without decisions.', 'State the decisions needed in the agenda, and end by reading back what was decided and what is open.'], ['Recording opinions as requirements.', 'Tag each statement as need, constraint, preference or proposed solution.'], ['Losing track of verbal agreements.', 'Publish notes quickly and ask attendees to correct them within a set window.']],
  collab: { biz: 'Confirm decision rights and get explicit sign-off on contested items.', design: 'Invite designers to observation sessions and usability conversations.', dev: 'Bring an engineer to workshops where feasibility or integration questions are likely.', qa: 'Share open questions; testers often spot missing rules first.', pm: 'Escalate blocked decisions to the product owner with options and impacts.' },
  tools: ['Teams or Zoom for remote workshops', 'Miro or FigJam boards', 'Confluence meeting-notes and decision templates', 'Excel or JIRA for the open-question register'],
  artifact: 'minutes', artifactNote: 'See Meeting minutes and decision log in the Artifact Studio.',
  related: ['workshops', 'conflict', 'comms', 'discovery'],
  cases: ['rajmarg', 'ats-vms'],
  q: { q: 'How do you handle two stakeholders who want opposite things?', a: 'I start by getting both positions written down as needs rather than solutions. With the mandatory-fields example, the applicant need is "submit without unnecessary effort" and the authority need is "have enough evidence to approve in compliance". I then work field by field: who uses it, at what stage, under which rule. That usually turns one argument into several smaller decisions, and some fields can move to a later stage. Anything still contested goes to the person with decision rights, with the options and their impacts, and the result goes into the decision log.' },
  more: ['Which elicitation technique do you rely on most, and why?', 'How do you elicit requirements from someone who is too busy to meet?', 'How do you know you have identified every stakeholder?'],
  honest: 'I name the stakeholder groups from my résumé (MoRTH, NHAI, DIC, engineering, QA and UI/UX) and describe my role as facilitating and documenting. I had no authority over client officials, and I don\'t imply that I did.'
},
{
  id: 'brd', area: 'A', name: 'BRD (Business Requirements Document)',
  tags: ['business objectives', 'scope', 'business rules', 'assumptions', 'constraints', 'success criteria', 'sign-off'],
  ev: 'source', evNote: 'Résumé: authored BRDs at Ascra, Intechglobe and Coditro.',
  sum: 'States what the business needs and why, in language the sponsor can approve.',
  def: 'A BRD records the business objectives, scope, exclusions, stakeholders, high-level business requirements, business rules, assumptions, constraints and success criteria for an initiative. It describes <em>what</em> the business needs and <em>why</em>, not how the system will do it.',
  why: 'The BRD is the baseline that sign-off, scope control and change requests refer back to. Without it, every later disagreement about scope becomes a disagreement about memory.',
  use: ['New modules, major enhancements or anything that needs sponsor approval.', 'Contracted or government work where scope must be formally agreed.'],
  avoid: ['Small backlog items in a mature product; a well-formed epic with acceptance criteria is enough.', 'As a substitute for functional detail; that belongs in the FRD or SRS.'],
  steps: ['Start from the confirmed problem statement and objectives from discovery.', 'Write scope and explicit exclusions; exclusions prevent most scope disputes.', 'List stakeholders and their responsibilities.', 'Write business requirements as numbered, testable statements (BR-01 …), each linked to an objective.', 'Capture business rules separately from requirements so they can change independently.', 'Record assumptions, constraints and dependencies, each with an owner.', 'Define success criteria and how they will be measured.', 'Review, revise, then obtain sign-off with a version number and date.'],
  scenario: 'An enhancement adds a structured clarification process to an application workflow. The BRD objective is "reduce avoidable back-and-forth between reviewers and applicants". In scope are reason codes, response windows and notifications. Out of scope are changes to the fee schedule or to eligibility rules. One assumption, "applicants have a registered email and mobile number", is owned by the onboarding team.',
  enterprise: 'An illustrative BRD excerpt in the Artifact Studio shows BR-01 to BR-06 for a clarification enhancement. Each requirement links to an objective, and the business rules carry their own IDs (RULE-…) so the RTM can trace them separately.',
  inputs: ['Problem statement', 'Stakeholder register', 'Policy documents', 'Discovery findings'],
  outputs: ['Signed-off BRD (versioned)', 'Baseline for change control and the RTM'],
  mistakes: [['Writing system behaviour in the BRD ("the system shall display a dropdown").', 'Keep it at business level: "Reviewers must record a reason for every clarification."'], ['No exclusions section.', 'List what is deliberately not included, and why.'], ['Unmeasurable success criteria ("improve efficiency").', 'Name the measure, data source and baseline period, even if the target is still to be agreed.']],
  collab: { biz: 'Sponsor and process owner approve; policy owner validates rules.', design: 'Designers use objectives and user groups to frame research.', dev: 'Architects check constraints and dependencies early.', qa: 'QA reads success criteria and rules to plan the test strategy.', pm: 'The product owner uses the BRD to frame the epic and roadmap.' },
  tools: ['Word or Confluence templates', 'Visio for context diagrams', 'SharePoint or Confluence for versioning and approvals'],
  artifact: 'brd', artifactNote: 'Open the BRD excerpt for a clarification-management enhancement.',
  related: ['frd', 'srs', 'rtm', 'rules', 'discovery'],
  cases: ['rajmarg', 'healthcare', 'ats-vms'],
  q: { q: 'What is the difference between a BRD and an FRD?', a: 'The BRD says what the business needs and why: objectives, scope, rules and success criteria, written for the sponsor to approve. The FRD says how the system must behave to meet those needs: roles, inputs, validations, outputs, exceptions. For example, the BRD says "reviewers must record a reason for each clarification". The FRD says "the clarification dialog shall require selecting at least one reason code from the configured list and shall allow up to 1,000 characters of remarks".' },
  more: ['Who signs off a BRD, and what happens after sign-off?', 'How do you manage changes to a signed BRD?'],
  honest: 'I authored BRDs on each project listed. I don\'t quote approved client documents; the excerpt here is a reconstructed example of my structure and approach.'
},
{
  id: 'frd', area: 'A', name: 'FRD (Functional Requirements Document)',
  tags: ['functional behaviour', 'roles', 'validations', 'exceptions', 'alternate flows', 'dependencies'],
  ev: 'source', evNote: 'Résumé: authored FRDs and functional specifications at Ascra, Intechglobe and Coditro.',
  sum: 'Turns each business need into precise, testable system behaviour, including the unhappy paths.',
  def: 'An FRD specifies the functions the system must perform: who can do what, what inputs are accepted, which validations apply, what outputs and status changes result, and what happens in alternate and exception flows.',
  why: 'Developers and testers need unambiguous behaviour. A business requirement such as "applicants can respond to clarifications" leaves many open questions: what happens after the deadline, what if the file is the wrong type, who is notified. The FRD answers them before code is written.',
  use: ['Module-level specification before or alongside sprint refinement.', 'Integrations and workflows with several roles and states.'],
  avoid: ['Restating UI pixel details that belong in design files.', 'Duplicating story-level detail that already lives, maintained, in JIRA; link to it instead.'],
  steps: ['Take each BR and decompose it into functional requirements (FR-xx) with a parent link.', 'Define actors and permissions for each function.', 'Specify inputs (field, type, mandatory/conditional, validation) and outputs (status change, notification, record).', 'Write the main flow, then alternate flows and exceptions.', 'List dependencies: other modules, integrations, master data.', 'Review with design, engineering and QA; resolve open questions.', 'Baseline and trace into the RTM.'],
  scenario: 'Business requirement BR-02 says applicants must be able to respond to a clarification. Its functional requirements are as follows. FR-07: the applicant sees the open clarification on the dashboard with the reviewer\'s reason and remarks. FR-08: the applicant can upload replacement documents (PDF, at most the configured size) and add a response note. FR-09: on submission the application returns to the same reviewer\'s queue with status "Clarification Responded". FR-10: if the response window lapses, the system applies the configured rule (for example, a reminder, then escalation). That rule is defined in the business rules catalogue, not hard-coded in the FRD.',
  enterprise: 'The Artifact Studio FRD table covers submission, clarification, approval, payment and notifications. Each row has an ID, actor, trigger, behaviour, validation, exception and parent BR.',
  inputs: ['Signed-off BRD', 'Business rules catalogue', 'Process maps', 'Wireframes'],
  outputs: ['FRD (versioned)', 'Functional requirement IDs for the RTM', 'Questions for design and engineering'],
  mistakes: [['Only describing the happy path.', 'For every function ask: invalid input, no permission, timeout, duplicate, and what if the user abandons it halfway?'], ['Mixing rules into prose.', 'Reference rule IDs so that a rule change does not mean rewriting every requirement.'], ['Using words like "quickly" or "appropriately".', 'Say exactly what happens, or mark the item as an open question.']],
  collab: { biz: 'Walk through flows with process owners using real sample cases.', design: 'Align states, messages and field rules with the design.', dev: 'Confirm feasibility and data availability.', qa: 'Each FR should yield test conditions; ask QA to review for testability.', pm: 'Use FR IDs to slice epics into stories.' },
  tools: ['Confluence or Word', 'Visio and Lucidchart', 'JIRA links', 'Excel for field-level specifications'],
  artifact: 'frd', artifactNote: 'Open the FRD requirements table.',
  related: ['brd', 'srs', 'rules', 'stories', 'ac'],
  cases: ['rajmarg', 'healthcare', 'ats-vms'],
  q: { q: 'Show me how a business requirement becomes functional requirements.', a: 'I would take "applicants can respond to a clarification" and break it into visible behaviour. Where the applicant sees it, what they can upload, what validations apply, what status the application moves to, who is notified, and what happens if the response window lapses. Each piece becomes an FR with a parent link to the BR. The FRs then trace to stories and test cases, so a later change to the response window shows exactly what to update.' },
  more: ['What makes a functional requirement testable?', 'How much detail is too much in an FRD?'],
  honest: 'I wrote FRDs and functional specifications. The tables in this portfolio are reconstructed examples, not client documents.'
},
{
  id: 'srs', area: 'A', name: 'SRS (Software Requirements Specification)',
  tags: ['system context', 'actors', 'interfaces', 'NFR', 'permissions', 'error handling', 'versioning'],
  ev: 'source', evNote: 'Résumé: authored SRS documents for Rajmarg Pravesh and DataLake 3.0 (Ascra).',
  sum: 'The full behavioural specification of a system, complete enough for design, build, integration and test.',
  def: 'An SRS is the comprehensive specification of a software system. It covers the system context, actors, functional requirements, non-functional requirements, external interfaces, data, permissions, error handling and traceability. Where the FRD is organised around business functions, the SRS describes the system as a whole and is often the contractual reference for vendors.',
  why: 'Large or multi-vendor builds need one source of truth that architects, developers, integrators and auditors can all use. A well-organised SRS also makes version-to-version change visible.',
  use: ['Government or contracted builds, multi-team programmes, systems with many integrations.', 'When audit or acceptance depends on a formal specification.'],
  avoid: ['Small product teams that keep specification in the backlog and design system; a lightweight product spec is better there.'],
  steps: ['Set the structure: introduction, scope, definitions, system context, actors, functional requirements by module, NFRs, interfaces, data, permissions matrix, error handling, traceability, change history.', 'Draw the context diagram showing every external system and the direction of data.', 'Write requirements with unique, stable IDs and module prefixes.', 'Add the permission matrix (role × function).', 'Specify interfaces: purpose, trigger, data, error handling and owner.', 'Define error handling and messages consistently.', 'Maintain a change-history table and mark changed requirements in each version.'],
  scenario: 'An SRS version adds a "re-upload bank guarantee" function. The Business Analyst adds new IDs and never renumbers existing ones. They flag each changed requirement in the change history and update the permission matrix, which says only the applicant can re-upload and only finance-role users can verify. The Business Analyst also adds an error case for when the document service is unavailable and updates the RTM.',
  enterprise: 'For a national permission portal, the context diagram would show the portal, identity/onboarding, GIS map service, document storage, payment gateway (for example a government receipts platform), e-signature service, SMS/email gateways and legacy data sources. Each interface section names a business owner and a technical owner.',
  inputs: ['BRD, FRD and business rules', 'Architecture and interface information', 'Security and NFR requirements'],
  outputs: ['Versioned SRS', 'Permission matrix', 'Interface catalogue', 'Updated RTM'],
  mistakes: [['Renumbering requirements between versions, which breaks traceability.', 'IDs are permanent. Deprecate instead of deleting.'], ['NFRs written as wishes ("fast", "secure").', 'Make them measurable or label targets as assumptions to validate.'], ['No error-handling section.', 'Define standard behaviour for validation errors, service failures and permission denials.']],
  collab: { biz: 'Business sign-off on functional sections.', design: 'Reference design specifications for UI behaviour.', dev: 'Architects co-author interface and NFR sections.', qa: 'QA uses it as the test basis.', pm: 'Product owner approves scope changes recorded in change history.' },
  tools: ['Word or Confluence', 'Visio, Draw.io or Lucidchart for context and UML diagrams', 'SharePoint for controlled versions'],
  artifact: 'srs', artifactNote: 'Open the SRS functional requirement sample.',
  related: ['frd', 'nfr', 'integrations', 'rbac', 'rtm'],
  cases: ['rajmarg', 'datalake'],
  q: { q: 'How do you keep an SRS maintainable over many releases?', a: 'Stable IDs that are never renumbered, a change-history table that names each changed requirement and the reason, deprecation instead of deletion, and the RTM updated in the same change. I also keep business rules in their own catalogue, so a rule change does not touch dozens of requirements.' },
  more: ['What goes into the system context section?', 'How do you document error handling in an SRS?'],
  honest: 'I authored SRS documents. I describe their structure and my practices, and I never reproduce or paraphrase confidential specifications.'
},
{
  id: 'stories', area: 'A', name: 'User stories',
  tags: ['INVEST', 'epic', 'feature', 'story splitting', 'tasks', 'defects'],
  ev: 'source', evNote: 'Résumé: user stories at all three Business Analyst roles; listed under Product & Agile skills.',
  sum: 'Small, valuable, testable slices of behaviour, written from the user\'s side.',
  def: 'A user story describes a capability from the point of view of the person who needs it: <em>As a [role], I want [capability] so that [benefit]</em>. It is a placeholder for a conversation, completed by acceptance criteria. <strong>Epic</strong>: a large body of work spanning several sprints. <strong>Feature</strong>: a user-recognisable capability, often grouping stories. <strong>Story</strong>: a slice deliverable in one sprint. <strong>Task</strong>: technical work needed to deliver a story. <strong>Defect</strong>: behaviour that differs from agreed requirements.',
  why: 'Stories keep delivery tied to user value and make work small enough to estimate, test and release. Well-split stories reduce sprint spillover and make progress visible.',
  use: ['Agile delivery of user-facing behaviour.', 'When a requirement can be delivered incrementally.'],
  avoid: ['Pure technical work with no user-visible result; use a task or enabler.', 'Writing stories as disguised tasks ("As a developer I want a table").'],
  steps: ['Start from the FR or epic and identify the user and the value.', 'Write the story in user language.', 'Add acceptance criteria, including negative and permission cases.', 'Check INVEST: Independent, Negotiable, Valuable, Estimable, Small, Testable.', 'Split if too large: by workflow step, role, business rule, data variation, happy path then exceptions, or interface.', 'Attach links to designs, rules and the parent epic.', 'Refine with the team until it meets the Definition of Ready.'],
  scenario: 'The epic is "Clarification management". It splits into separate stories. The reviewer raises a clarification with a reason code. The applicant views the clarification on the dashboard. The applicant uploads a response. The reviewer resumes processing. The system reminds the applicant before the response window ends. The admin configures reason codes. Each story can be built and tested on its own, and the first three already form a usable increment.',
  enterprise: '<strong>Applicant:</strong> As an applicant, I want to see exactly which document a reviewer has asked for, so that I can respond once instead of guessing. <strong>Reviewer:</strong> As a reviewing officer, I want to filter my queue by "Clarification Responded", so that I can resume files that are ready. <strong>Administrator:</strong> As an administrator, I want to maintain clarification reason codes, so that reviewers use consistent language. <strong>Finance user:</strong> As a finance user, I want to see payments that failed reconciliation, so that I can resolve them before the application is approved.',
  inputs: ['FRD and business rules', 'Personas and journeys', 'Designs'],
  outputs: ['Refined stories with acceptance criteria', 'Story map', 'Split stories ready for sprint planning'],
  mistakes: [['Stories too large to finish in a sprint.', 'Split by workflow step or rule; deliver the happy path first, then exceptions.'], ['No "so that".', 'If you cannot state the value, question whether the story is needed.'], ['Acceptance criteria missing negative paths.', 'Add at least one invalid input, one permission case and one exception per story.']],
  collab: { biz: 'Validate value and priority.', design: 'Link the designs and states that each story covers.', dev: 'Agree on splitting and tasks during refinement.', qa: 'QA reviews acceptance criteria for testability.', pm: 'Product owner orders stories in the backlog.' },
  tools: ['JIRA', 'Confluence', 'Miro story maps', 'Figma links'],
  artifact: 'story', artifactNote: 'Open the User story and acceptance criteria artifact.',
  related: ['ac', 'backlog', 'jira', 'dor-dod'],
  cases: ['rajmarg', 'healthcare', 'ats-vms'],
  q: { q: 'How do you split a large story?', a: 'I look for a thin slice that still delivers value end to end. For clarification management, the first slice is: the reviewer raises a clarification with a reason, the applicant sees it and responds, and the file returns to the reviewer. Reminders, escalation, reason-code administration and reporting come as later stories. Each slice has its own acceptance criteria and can be tested independently.' },
  more: ['What is the difference between an epic, a feature and a story?', 'Who writes user stories on your teams?'],
  honest: 'I have written user stories in every Business Analyst role. The stories here are illustrative and are not copied from client backlogs.'
},
{
  id: 'ac', area: 'A', name: 'Acceptance criteria',
  tags: ['Given When Then', 'Gherkin', 'negative paths', 'boundary', 'permissions', 'audit'],
  ev: 'source', evNote: 'Résumé: acceptance criteria at Ascra and Coditro; listed under Product & Agile skills.',
  sum: 'The agreed conditions a story must meet to be accepted: clear enough to test, free of implementation detail.',
  def: 'Acceptance criteria are the conditions a story must satisfy before the product owner accepts it. They describe observable behaviour, including negative paths, boundaries, permission checks, exceptions and audit expectations. Given–When–Then is a common format: the context, the action, the expected outcome.',
  why: 'They are the contract between business, development and testing for a single story. Clear criteria reduce rework, settle "is it done?" arguments, and become the basis for test cases.',
  use: ['Every user story.', 'Defects too, to state the corrected behaviour.'],
  avoid: ['Writing implementation instructions ("use a modal", "add column X to table Y").', 'Writing full test scripts; test cases expand criteria with data and steps.'],
  steps: ['Write the happy path first.', 'Add negative paths: invalid input, missing data.', 'Add boundaries: limits, dates, sizes.', 'Add permission checks: who must not be able to do this.', 'Add exceptions: service unavailable, concurrent edits.', 'Add audit: what must be recorded.', 'Review with QA and developers in refinement.'],
  scenario: 'The reviewer raises a clarification, the applicant responds, and the reviewer resumes processing. <br><strong>AC1:</strong> Given an application in "Under Review" assigned to me, when I raise a clarification with at least one reason code, then the status becomes "Clarification Raised", the applicant is notified, and the clarification is recorded with my user ID and timestamp. <br><strong>AC2:</strong> Given a raised clarification, when the applicant submits a response with the requested document, then the status becomes "Clarification Responded" and the file returns to my queue. <br><strong>AC3:</strong> Given I select no reason code, when I submit, then I see "Select at least one reason" and nothing is saved. <br><strong>AC4:</strong> Given I am not the assigned reviewer, when I open the application, then the raise-clarification action is not available. <br><strong>AC5:</strong> Given "Clarification Responded", when I resume, then the status returns to "Under Review" and the history shows the complete clarification cycle.',
  enterprise: 'Acceptance criteria are not test cases. AC3 states the rule. The test cases built from it would cover submitting with no reason, submitting with one reason, and submitting with the maximum number of reasons, each with specific data and expected messages.',
  inputs: ['User story', 'Business rules', 'Designs and messages'],
  outputs: ['Testable acceptance criteria attached to the story'],
  mistakes: [['Vague outcomes ("works correctly").', 'State the observable result: status, message, record, notification.'], ['Implementation detail.', 'Describe behaviour. Let design and engineering choose the mechanism.'], ['Only happy path.', 'Use a checklist: negative, boundary, permission, exception, audit.']],
  collab: { biz: 'The product owner accepts against them.', design: 'Messages and states align with the design.', dev: 'Developers raise feasibility issues during refinement.', qa: 'Testers derive test cases and spot missing conditions.', pm: 'They help the product owner say "done" with confidence.' },
  tools: ['JIRA story description or checklist', 'Gherkin in test tools', 'Confluence for shared rule references'],
  artifact: 'story', artifactNote: 'Open the User story and acceptance criteria artifact.',
  related: ['stories', 'testing', 'uat', 'rules'],
  cases: ['rajmarg', 'ats-vms'],
  q: { q: 'What is the difference between acceptance criteria and test cases?', a: 'Acceptance criteria state the conditions the story must meet: for example, that a clarification cannot be raised without a reason. Test cases are the concrete checks that prove it, with preconditions, data, steps and expected results, including variants such as one reason, several reasons and none. One criterion usually produces several test cases.' },
  more: ['How do you write acceptance criteria for a permission rule?', 'Should acceptance criteria include UI text?'],
  honest: 'I wrote acceptance criteria for stories on the projects listed. The specific criteria here are illustrative.'
},
{
  id: 'rtm', area: 'A', name: 'Requirements Traceability Matrix (RTM)',
  tags: ['forward traceability', 'backward traceability', 'impact analysis', 'coverage', 'test mapping'],
  ev: 'source', evNote: 'Résumé: authored RTMs at Ascra, Intechglobe and Coditro.',
  sum: 'Links every objective to its requirements, stories, designs, tests and release, so nothing is lost and every change has a known blast radius.',
  def: 'An RTM is a table, or set of tool links, connecting business objectives to business requirements, functional requirements, user stories, design references, test cases, defects and releases. <strong>Forward traceability</strong> checks that every requirement is built and tested. <strong>Backward traceability</strong> checks that everything built exists for an approved reason.',
  why: 'It shows coverage gaps before UAT, gives audit evidence, and makes impact analysis fast: when a rule changes, the RTM shows which stories, tests and documents must change with it.',
  use: ['Formal or audited delivery.', 'Programmes with frequent change requests.', 'Before UAT sign-off to prove coverage.'],
  avoid: ['Maintaining a manual spreadsheet that duplicates tool links nobody updates. Pick one source of truth.'],
  steps: ['Define the chain and ID conventions (OBJ → BR → FR → US → TC → REL).', 'Populate as requirements are approved, not at the end.', 'Link test cases when written; link defects as they are raised.', 'Review coverage before each sprint review and before UAT.', 'On change, filter by the changed ID and list every downstream item.', 'Keep version and status columns current.'],
  scenario: 'The rule "an applicant has 15 days to respond to a clarification" changes to a configurable value. (15 is an illustrative number.) Filtering the RTM by RULE-04 shows three FRs, four stories, nine test cases, one report definition, the applicant user manual and the SOP section. All of them go into the change-impact analysis.',
  enterprise: 'The Artifact Studio RTM shows rows from OBJ-1 ("reduce avoidable clarification cycles") through to release, with coverage status.',
  inputs: ['BRD, FRD, SRS', 'Backlog', 'Test cases', 'Release plan'],
  outputs: ['RTM', 'Coverage report', 'Change-impact list'],
  mistakes: [['Building the RTM just before UAT.', 'Maintain it continuously.'], ['Tracing only to stories, not tests.', 'Coverage needs test links and results.'], ['No backward check.', 'Look for stories with no parent requirement; they are scope creep or missing documentation.']],
  collab: { biz: 'Shows sponsors that approved scope is covered.', design: 'Link the designs for traceability of UI changes.', dev: 'Developers see why a story exists.', qa: 'QA maintains test links and results.', pm: 'Product owner uses it for scope and release decisions.' },
  tools: ['Excel', 'JIRA issue links and test-management add-ons', 'Confluence tables'],
  artifact: 'rtm', artifactNote: 'Open the RTM with change-impact example.',
  related: ['brd', 'frd', 'testing', 'gap', 'release'],
  cases: ['rajmarg', 'healthcare', 'ats-vms'],
  q: { q: 'How have you used an RTM beyond compliance?', a: 'Mainly for impact analysis and UAT readiness. When a rule changes, filtering by the rule ID gives the exact list of stories, test cases and documents to update, which turns "what does this affect?" from a meeting into a query. Before UAT, I check forward coverage so that no approved requirement arrives without test cases.' },
  more: ['What columns do you include in an RTM?', 'Who maintains it?'],
  honest: 'I authored RTMs and describe how I used them. I don\'t quote real requirement IDs or counts from client projects.'
},
{
  id: 'rules', area: 'A', name: 'Business rules and validation logic',
  tags: ['decision table', 'pseudocode', 'conditional fields', 'eligibility', 'fees', 'duplicates', 'boundary values'],
  ev: 'recommended', evNote: 'Applied inside source-supported FRD and functional-specification work; the specific rules shown here are illustrative.',
  sum: 'Rules the business lives by, written once, in plain language, with their exceptions and boundaries.',
  def: 'A business rule is a statement that defines or constrains some aspect of the business: who is eligible, what is mandatory, how a fee is calculated, when a document is valid. Validation logic is how the system enforces those rules at the point of input or decision.',
  why: 'Rules change more often than workflows. Keeping them in a catalogue with IDs, owners and sources makes them reviewable by policy owners, testable by QA, and changeable without rewriting every requirement.',
  use: ['Mandatory and conditional fields', 'Role-based rules', 'Eligibility', 'Fee calculation', 'Date and validity checks', 'Duplicate detection', 'Exceptions'],
  avoid: ['Encoding policy you have not confirmed with its owner. Mark it as an open question instead.'],
  steps: ['Collect rules from policy, SOPs and stakeholders; record the source.', 'Write each rule in plain language with an ID and owner.', 'Where conditions combine, use a decision table.', 'Where logic is sequential, add pseudocode.', 'List boundary values and negative cases.', 'Review with the policy owner and QA.', 'Reference rule IDs from requirements and tests.'],
  scenario: '<strong>Illustrative rules for a permission application.</strong><br>RULE-01 Mandatory: an application cannot be submitted without the documents mandatory for its application type. <br>RULE-02 Conditional: if the applicant is a company, a registration number and authorised-signatory document are required. <br>RULE-03 Date: a bank guarantee\'s validity end date must be on or after the required minimum date. <br>RULE-04 Response window: an applicant responds to a clarification within the configured number of days. <br>RULE-05 Duplicate: warn if an active application exists for the same applicant, highway and overlapping chainage. <br>RULE-06 Role: only the assigned reviewer can raise a clarification. <br><br><strong>Pseudocode for RULE-03</strong><pre><code>IF bg.valid_to &lt; required_min_date THEN\n   reject upload with message "Bank guarantee validity ends before the required date (dd-mm-yyyy). Upload a guarantee valid until at least that date."\nELSE IF bg.valid_to = required_min_date THEN\n   accept   // boundary: exactly equal is valid\nELSE accept</code></pre>',
  enterprise: '<strong>Boundary and negative scenarios for RULE-03</strong>: validity ends one day before the required date (reject), exactly on it (accept), one day after (accept); date missing (reject with a field message); issue date after expiry date (reject). The decision table in the Artifact Studio covers the "missing information" combinations.',
  inputs: ['Policies, circulars and SOPs', 'Stakeholder decisions'],
  outputs: ['Rules catalogue', 'Decision tables', 'Pseudocode', 'Boundary test list'],
  mistakes: [['Rules buried in story text.', 'Use a catalogue with IDs and reference them.'], ['Ignoring the boundary ("before" vs "on or before").', 'Ask the owner explicitly and write the boundary into the rule.'], ['Hard-coding values that policy changes.', 'Identify configurable parameters.']],
  collab: { biz: 'Policy owner validates the wording and source.', design: 'Messages explain the rule and how to fix the problem.', dev: 'Engineers decide where each rule is enforced (client, server, both).', qa: 'QA builds boundary and negative tests from the catalogue.', pm: 'Product owner decides on configurability.' },
  tools: ['Excel or Confluence rules catalogue', 'Decision tables', 'JIRA links'],
  artifact: 'decision', artifactNote: 'Open the interactive Decision table.',
  related: ['frd', 'ac', 'testing', 'uat'],
  cases: ['rajmarg', 'healthcare', 'ats-vms'],
  q: { q: 'How do you document a complex rule so that developers and testers read it the same way?', a: 'I write it in plain language with an ID, owner and source. Then I add a decision table for the combinations and pseudocode if order matters, and list the boundary cases explicitly. For example, for a guarantee validity rule I would state whether "on the required date" is valid and include the one-day-before and exact-date tests.' },
  more: ['Where should validation happen: front end or back end?', 'How do you handle rules that differ by region?'],
  honest: 'These rules were written for this portfolio to show the method. They are not the actual policy of any authority.'
},
{
  id: 'process', area: 'A', name: 'Process modelling and workflow design',
  tags: ['BPMN', 'swimlanes', 'current state', 'future state', 'UML', 'escalation', 'exception paths'],
  ev: 'source', evNote: 'Résumé: Workflow Design, Process Mapping, UML; workflow diagrams in Visio across roles; workflow automation and 10+ workflow modules (Ascra).',
  sum: 'Shows who does what, in which order, with which decisions and exceptions, before and after the change.',
  def: 'Process modelling represents work as activities, decisions, events and handoffs across roles (swimlanes). BPMN (Business Process Model and Notation) is a standard notation. Current-state models show how work happens today; future-state models show the intended process with the new system.',
  why: 'Workflows are where multi-role systems usually fail: a missing return path, an unclear handoff, a status with no exit. Drawing the process exposes these before they become defects.',
  use: ['Any multi-step, multi-role workflow.', 'Status design and SLA definition.', 'Training and SOPs.'],
  avoid: ['Modelling every keystroke. Model decisions, handoffs and states.'],
  steps: ['Define scope: trigger, end states, participants.', 'Draw current state from evidence.', 'Mark pain points and delays.', 'Design future state with decisions, alternate paths, rejection loops, escalation and exceptions.', 'Derive the status model from the future state.', 'Validate with each role by walking through real cases.', 'Link process steps to requirements.'],
  scenario: 'For an application process, the future state has six lanes: Applicant, Portal, Reviewing Officer, Field Inspector, Approving Authority and Finance. The key paths are the clarification loop (reviewer to applicant and back), site inspection, provisional approval leading to payment and the bank guarantee, and final approval with an e-signature. Exceptions include a response window lapse (escalation), payment failure (retry or reconcile) and an invalid guarantee (re-upload).',
  enterprise: 'The interactive workflow in the Rajmarg Pravesh case study and the BPMN artifact lets you click each step to see the role, the rule, the status change and the related requirement. It is a reconstructed, illustrative model, not the production configuration.',
  inputs: ['SOPs and policy', 'Observation and interviews', 'System records'],
  outputs: ['Current and future-state diagrams', 'Status model', 'Exception catalogue'],
  mistakes: [['Diagrams with no exception paths.', 'For every decision, draw every outcome.'], ['Statuses that do not match the diagram.', 'Derive statuses from the model and check each has an exit.'], ['No owner for each step.', 'Every activity sits in a lane.']],
  collab: { biz: 'Process owners validate each lane.', design: 'Each step becomes a screen state or a notification.', dev: 'Engineers map it to workflow engine configuration.', qa: 'Each path becomes a test scenario.', pm: 'Product owner uses it to scope increments.' },
  tools: ['Microsoft Visio', 'Draw.io', 'Lucidchart', 'Miro or FigJam for workshops'],
  artifact: 'bpmn', artifactNote: 'Open the interactive BPMN-style workflow.',
  related: ['gap', 'rules', 'frd', 'metrics'],
  cases: ['rajmarg', 'healthcare', 'ats-vms'],
  q: { q: 'Walk me through a workflow you designed.', a: 'I would walk through the application workflow: submission, scrutiny, clarification loop, inspection, provisional approval, payment and guarantee, final approval. I would focus on the decisions and exceptions: what happens when a response is late, when a payment fails, when a guarantee is invalid. Then I would explain that the status list was derived from that model so that every status has an owner and an exit.' },
  more: ['How do you validate a process model?', 'What is the difference between current and future state, and why model both?'],
  honest: 'I created workflow diagrams in Visio. The diagram here is a reconstruction for illustration, and I say so if asked.'
},
{
  id: 'gap', area: 'A', name: 'Gap analysis and impact analysis',
  tags: ['current vs desired', 'process gaps', 'system gaps', 'policy dependency', 'change impact'],
  ev: 'source', evNote: 'Résumé: GAP Analysis (skills; Coditro); impact assessment implied by change management and RTM work.',
  sum: 'Compares where we are with where we need to be, and works out everything a change will touch.',
  def: '<strong>Gap analysis</strong> compares the current state with the desired state and lists the gaps in process, system, data, policy and skills. <strong>Impact analysis</strong> examines a proposed change and identifies everything it affects: workflows, roles, data, integrations, reports, tests, documentation and training.',
  why: 'Gap analysis turns vague ambitions into a concrete work list. Impact analysis prevents the classic surprise where a "small" change breaks a report, an integration or a training manual.',
  use: ['Assessing a product or vendor against needs.', 'Migrating from legacy processes.', 'Every change request.'],
  avoid: ['Generic gap lists with no owner or priority.'],
  steps: ['Define the desired state (policy, target process, required capabilities).', 'Document the current state.', 'List gaps by category with evidence.', 'Classify each gap: process, system, data, policy, people.', 'For a change, trace through the RTM and architecture to list affected items.', 'Rate effort and risk, and identify policy dependencies.', 'Recommend actions and owners.'],
  scenario: 'Change request: allow applicants to re-upload a bank guarantee after a validity issue. The impact analysis covers the following. Workflow: a new loop from verification back to the applicant. Roles: applicant re-uploads, finance re-verifies. Data: guarantee version history. Notifications: new templates. Reports: guarantee ageing. Tests: new and regression cases. Documentation: SOP and user manual. Training: finance users. Policy dependency: is there a limit on re-uploads?',
  enterprise: 'The Change-impact analysis artifact shows this as a structured table with impact level, owner and action for each area.',
  inputs: ['Desired-state definition', 'Current-state model', 'RTM', 'Architecture overview'],
  outputs: ['Gap register', 'Change-impact analysis', 'Recommendations'],
  mistakes: [['Ignoring non-system impacts.', 'Always check documents, training, reports and SOPs.'], ['No policy owner for policy gaps.', 'Escalate them; the system cannot decide policy.']],
  collab: { biz: 'Validate the desired state and accept the gaps.', design: 'Design assesses UI impact.', dev: 'Engineering assesses technical effort and risk.', qa: 'QA identifies regression scope.', pm: 'Product owner prioritises gap closure.' },
  tools: ['Excel', 'Confluence', 'Visio', 'JIRA'],
  artifact: 'impact', artifactNote: 'Open the Change-impact analysis.',
  related: ['rtm', 'process', 'release', 'migration'],
  cases: ['rajmarg', 'ats-vms'],
  q: { q: 'How do you do an impact analysis for a change request?', a: 'I start from the RTM to find affected requirements, stories and tests. Then I check a fixed list: workflow and statuses, roles and permissions, data and history, integrations, notifications, reports, documentation, training, and policy dependencies. Each impact gets a level and an owner, and the product owner decides whether and when to take the change.' },
  more: ['Give an example of a gap you found that was not a system gap.'],
  honest: 'Gap analysis is part of my résumé. The bank guarantee change is an illustrative scenario from the case study.'
},
{
  id: 'nfr', area: 'A', name: 'Non-functional requirements',
  tags: ['performance', 'availability', 'security', 'accessibility', 'scalability', 'auditability', 'usability'],
  ev: 'recommended', evNote: 'Not listed explicitly in the résumé; part of SRS authoring (source-supported). Targets shown are illustrative assumptions.',
  sum: 'How well the system must behave: speed, reliability, security, accessibility and auditability, made measurable.',
  def: 'Non-functional requirements (NFRs) describe qualities rather than functions. They cover performance (response time), availability (uptime), security (access control, data protection), accessibility (usable by people with disabilities), scalability (handling growth), usability, auditability (who did what, when), reliability and maintainability.',
  why: 'Many go-live failures are non-functional: the system works but is slow under load, inaccessible, or cannot prove who approved what. NFRs make these qualities explicit and testable.',
  use: ['Every SRS.', 'Public-facing portals with large user bases.', 'Any system with approvals or payments (auditability).'],
  avoid: ['Inventing numbers. Targets should come from policy, contract, architecture or measured baselines, or be labelled as assumptions to validate.'],
  steps: ['Use a checklist of quality categories.', 'Ask stakeholders about scenarios ("what happens at the last day of a deadline?").', 'Ask engineering what is feasible and how it can be measured.', 'Write each NFR with a measure, condition and verification method.', 'Mark unconfirmed targets as assumptions.', 'Trace NFRs to tests (performance, security, accessibility).'],
  scenario: '<strong>Illustrative NFRs (assumed targets to validate with the technical team):</strong><br>NFR-PERF-01: Application search results return within 3 seconds for 95% of requests under expected peak load (target to be confirmed by architecture). <br>NFR-AUD-01: Every status change records user ID, role, timestamp, previous status, new status and remarks; records cannot be edited. <br>NFR-ACC-01: Public forms meet WCAG 2.1 AA (government accessibility guidelines may apply; confirm the applicable standard). <br>NFR-SEC-01: Sessions expire after a period of inactivity defined by the security policy.',
  enterprise: 'The Business Analyst rarely sets these targets alone. They facilitate the conversation: the business says what matters ("reviewers cannot wait while files load at month end"), engineering says what is measurable and feasible, and the Business Analyst writes the result down and traces it to a test.',
  inputs: ['Policy and contract', 'Architecture', 'Usage patterns'],
  outputs: ['NFR section of the SRS', 'Test approach for each NFR'],
  mistakes: [['"The system should be fast."', 'Measure, condition, verification method.'], ['Numbers without a source.', 'Label as an assumption and name who will confirm it.']],
  collab: { biz: 'Describe the business impact of slowness or downtime.', design: 'Accessibility and usability standards.', dev: 'Architects confirm feasibility and measurement.', qa: 'Performance and security testing.', pm: 'Product owner balances cost and quality.' },
  tools: ['SRS template', 'Confluence', 'Performance and accessibility testing tools (owned by technical teams)'],
  artifact: 'srs', artifactNote: 'See the NFR section of the SRS sample.',
  related: ['srs', 'rbac', 'usability'],
  cases: ['rajmarg', 'healthcare'],
  q: { q: 'How do you define non-functional requirements when stakeholders cannot give numbers?', a: 'I ask scenario questions about the business impact, for example what happens if search is slow on the busiest day. I take those to engineering to agree what is measurable. If a target is still unknown, I write it as an assumption with an owner and a date to confirm, rather than inventing a number.' },
  more: ['Which NFRs matter most for a government portal?'],
  honest: 'This is my approach to non-functional requirements. The targets shown are illustrative assumptions, not project commitments.'
}
);
